package GUI;
import GUI.components.TransactionTable; import Program.model.*; import Program.service.TransactionService; import javafx.collections.*; import javafx.collections.transformation.*; import javafx.scene.control.*; import javafx.scene.layout.*; import java.util.*;
public class TransactionUI extends ScrollPane {public TransactionUI(User u,MainUI app){setFitToWidth(true);TransactionService service=new TransactionService();VBox p=UIFactory.page("Transactions","One unified timeline for income and expenses — powered by polymorphism.");TextField search=UIFactory.field("Search description or category");ComboBox<String>type=new ComboBox<>();type.getItems().addAll("All types","Income","Expense");type.setValue("All types");ComboBox<String> category=new ComboBox<>();category.getItems().add("All categories");service.all(u.getId()).stream().map(Transaction::getCategory).distinct().sorted().forEach(category.getItems()::add);category.setValue("All categories");TransactionTable table=new TransactionTable();ObservableList<Transaction>all=FXCollections.observableArrayList(service.all(u.getId()));FilteredList<Transaction>filtered=new FilteredList<>(all,x->true);table.setItems(filtered);Runnable filter=()->filtered.setPredicate(t->(search.getText().isBlank()||(t.getCategory()+" "+t.getDescription()).toLowerCase().contains(search.getText().toLowerCase()))&&(type.getValue().equals("All types")||t.getType().equals(type.getValue()))&&(category.getValue().equals("All categories")||t.getCategory().equals(category.getValue())));search.textProperty().addListener((o,a,b)->filter.run());type.valueProperty().addListener((o,a,b)->filter.run());category.valueProperty().addListener((o,a,b)->filter.run());HBox f=new HBox(10,search,type,category);HBox.setHgrow(search,Priority.ALWAYS);p.getChildren().addAll(f,table);setContent(p);}}
